import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()
    # strip whitespace from text columns and normalize empty strings to NaN
    for col in ["Category", "Region", "Date", "Product"]:
        if col in df.columns:
            # preserve NaN
            mask = df[col].notna()
            df.loc[mask, col] = df.loc[mask, col].astype(str).str.strip()
            df[col] = df[col].replace('', np.nan)
    # fix Category label variants
    if "Category" in df.columns:
        df["Category"] = df["Category"].replace({
            "Office Suplies": "Office Supplies",
            "Accesories": "Accessories"
        })
    # ensure numeric types (handles text_number if present)
    for col in ["Quantity", "Price", "Revenue"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")
    # enforce Revenue formula: Revenue = Quantity * Price
    if "Quantity" in df.columns and "Price" in df.columns:
        df["Revenue"] = df["Quantity"] * df["Price"]
    # drop exact duplicate rows (Order_ID duplicate in sample rows 3/4)
    df = df.drop_duplicates()
    # also ensure Order_ID uniqueness - keep first occurrence
    if "Order_ID" in df.columns:
        df = df.drop_duplicates(subset=["Order_ID"], keep="first")
    # optional: coerce invalid dates to NaT (invalid_date handling)
    if "Date" in df.columns:
        df["Date"] = pd.to_datetime(df["Date"], errors="coerce")
    return df

def answer(df):
    # group by Category and sum Revenue, drop missing group keys
    d = df.dropna(subset=["Category"])
    if d.empty:
        return {}
    grouped = d.groupby("Category", dropna=True)["Revenue"].sum()
    result = {}
    for k, v in grouped.items():
        if pd.isna(k):
            continue
        # convert numpy types to native python int/float
        fv = float(v)
        if fv.is_integer():
            result[str(k)] = int(fv)
        else:
            result[str(k)] = fv
    return result
